document.addEventListener("DOMContentLoaded", function () {
  const logo = document.querySelector(".hero_home_logo-typo");
  const list = document.querySelector(".hero_home_categories");

  setTimeout(() => {
    logo.classList.add("slide-up");

    setTimeout(() => {
      list.classList.remove("hidden");
      list.classList.add("slide-in");
    }, 500);
  }, 2000);
});
